const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const n = tok[0], m = tok[1];
const adj = Array.from({ length: n + 1 }, () => []);
const radj = Array.from({ length: n + 1 }, () => []);
for (let i = 0; i < m; i++) {
  const u = tok[2 + 2 * i], v = tok[3 + 2 * i];
  adj[u].push(v);
  radj[v].push(u);
}
const seen = new Array(n + 1).fill(false);
const order = [];
function dfs1(v) {
  seen[v] = true;
  for (const to of adj[v]) if (!seen[to]) dfs1(to);
  order.push(v);
}
for (let s = 1; s <= n; s++) if (!seen[s]) dfs1(s);
const seen2 = new Array(n + 1).fill(false);
function dfs2(v) {
  seen2[v] = true;
  let c = 1;
  for (const to of radj[v]) if (!seen2[to]) c += dfs2(to);
  return c;
}
const sizes = [];
for (let i = order.length - 1; i >= 0; i--) {
  if (!seen2[order[i]]) sizes.push(dfs2(order[i]));
}
sizes.sort((a, b) => b - a);
console.log(sizes.length + "\n" + sizes.join(" "));

