import java.io.*;
import java.util.*;

public class Main {
    static List<Integer>[] adj, radj;
    static boolean[] seen, seen2;
    static int[] order;
    static int cnt = 0;

    static void dfs1(int v) {
        seen[v] = true;
        for (int to : adj[v]) if (!seen[to]) dfs1(to);
        order[cnt++] = v;
    }

    static int dfs2(int v) {
        seen2[v] = true;
        int c = 1;
        for (int to : radj[v]) if (!seen2[to]) c += dfs2(to);
        return c;
    }

    @SuppressWarnings("unchecked")
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        adj = new List[n + 1];
        radj = new List[n + 1];
        for (int i = 0; i <= n; i++) { adj[i] = new ArrayList<>(); radj[i] = new ArrayList<>(); }
        for (int i = 0; i < m; i++) {
            in.nextToken();
            int u = (int) in.nval;
            in.nextToken();
            int v = (int) in.nval;
            adj[u].add(v);
            radj[v].add(u);
        }
        seen = new boolean[n + 1];
        seen2 = new boolean[n + 1];
        order = new int[n];
        for (int s = 1; s <= n; s++) if (!seen[s]) dfs1(s);
        List<Integer> sizes = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) if (!seen2[order[i]]) sizes.add(dfs2(order[i]));
        sizes.sort(Collections.reverseOrder());
        StringBuilder out = new StringBuilder();
        out.append(sizes.size()).append('\n');
        for (int i = 0; i < sizes.size(); i++) out.append(i > 0 ? " " : "").append(sizes.get(i));
        System.out.println(out);
    }
}

