#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj, radj;
vector<bool> seen, seen2;
vector<int> order_;

void dfs1(int v) {
    seen[v] = true;
    for (int to : adj[v]) if (!seen[to]) dfs1(to);
    order_.push_back(v);
}
int dfs2(int v) {
    seen2[v] = true;
    int c = 1;
    for (int to : radj[v]) if (!seen2[to]) c += dfs2(to);
    return c;
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    adj.assign(n + 1, {});
    radj.assign(n + 1, {});
    for (int i = 0; i < m; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        radj[v].push_back(u);
    }
    seen.assign(n + 1, false);
    seen2.assign(n + 1, false);
    for (int s = 1; s <= n; s++) if (!seen[s]) dfs1(s);
    vector<int> sizes;
    for (int i = (int)order_.size() - 1; i >= 0; i--)
        if (!seen2[order_[i]]) sizes.push_back(dfs2(order_[i]));
    sort(sizes.rbegin(), sizes.rend());
    printf("%d\n", (int)sizes.size());
    for (size_t i = 0; i < sizes.size(); i++) printf(i ? " %d" : "%d", sizes[i]);
    printf("\n");
    return 0;
}
